import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import DiscussionList from 'flarum/forum/components/DiscussionList';
import DiscussionPage from 'flarum/forum/components/DiscussionPage';
import IndexPage from 'flarum/forum/components/IndexPage';
import Button from 'flarum/common/components/Button';
app.initializers.add('flarum-pusher', () => {
  app.pusher = (async () => {
    // @ts-expect-error
    await import('//cdn.jsdelivr.net/npm/pusher-js@7.0.3/dist/web/pusher.min.js' /* webpackIgnore: true, webpackPrefetch: true */);

    // @ts-expect-error Imported dynamically
    const socket = new Pusher(app.forum.attribute('pusherKey'), {
      authEndpoint: `${app.forum.attribute('apiUrl')}/pusher/auth`,
      cluster: app.forum.attribute('pusherCluster'),
      wsHost: 'soketi.sessizbilgi.com',
      wsPort: 443,
      wssPort: 443,
      forceTLS: true,
      disableStats: true,
      enabledTransports: ['ws', 'wss'],
      auth: {
        headers: {
          'X-CSRF-Token': app.session.csrfToken
        }
      }
    });
    return {
      channels: {
        main: socket.subscribe('public'),
        user: app.session.user ? socket.subscribe(`private-user${app.session.user.id()}`) : null
      },
      pusher: socket
    };
  })();
  app.pushedUpdates = [];
  extend(DiscussionList.prototype, 'oncreate', function () {
    this.boundNewPostHandler = rawData => {
      try {
        // Pusher verisi string geldiyse JSON nesnesine çeviriyoruz (Kritik Çözüm)
        const data = typeof rawData === 'string' ? JSON.parse(rawData) : rawData;
        console.log('[Sonsuzus Pusher] Yeni mesaj işleniyor:', data);
        const params = this.attrs.state.getParams();
        if (!params.q && !params.sort && !params.filter) {
          if (params.tags) {
            const tag = app.store.getBy('tags', 'slug', params.tags);
            const tagId = tag?.id();
            if (!tagId || !(data.tagIds || []).map(String).includes(tagId)) return;
          }
          const id = String(data.discussionId);
          if ((!app.current.get('discussion') || id !== app.current.get('discussion').id()) && app.pushedUpdates.indexOf(id) === -1) {
            app.pushedUpdates.push(id);
            console.log('[Sonsuzus Pusher] Buton tetiklendi. Bekleyen tartışma sayısı:', app.pushedUpdates.length);
            if (app.current.matches(IndexPage)) {
              app.setTitleCount(app.pushedUpdates.length);
            }
            m.redraw();
          }
        }
      } catch (e) {
        console.error('[Sonsuzus Pusher] newPost işlenirken hata oluştu:', e);
      }
    };
    app.pusher.then(binding => {
      binding.pusher.bind('newPost', this.boundNewPostHandler);
    });
  });
  extend(DiscussionList.prototype, 'onremove', function () {
    if (this.boundNewPostHandler) {
      app.pusher.then(binding => {
        binding.pusher.unbind('newPost', this.boundNewPostHandler);
      });
    }
  });
  extend(DiscussionList.prototype, 'view', function (vdom) {
    if (app.pushedUpdates && app.pushedUpdates.length > 0) {
      const count = app.pushedUpdates.length;
      if (vdom && vdom.children && Array.isArray(vdom.children)) {
        vdom.children.unshift(m(Button, {
          className: "Button Button--block DiscussionList-update",
          onclick: () => {
            this.attrs.state.refresh().then(() => {
              this.loadingUpdated = false;
              app.pushedUpdates = [];
              app.setTitleCount(0);
              m.redraw();
            });
            this.loadingUpdated = true;
          },
          loading: this.loadingUpdated
        }, app.translator.trans('flarum-pusher.forum.discussion_list.show_updates_text', {
          count
        })));
      }
    }
  });
  extend(DiscussionPage.prototype, 'oncreate', function () {
    this.boundNewPostHandler = rawData => {
      try {
        const data = typeof rawData === 'string' ? JSON.parse(rawData) : rawData;
        const id = String(data.discussionId);
        const discussionId = this.discussion?.id();
        if (this.discussion && discussionId === id && this.stream) {
          const oldCount = this.discussion.commentCount() ?? 0;
          app.store.find('discussions', discussionId).then(() => {
            this.stream?.update().then(m.redraw);
            if (!document.hasFocus()) {
              app.setTitleCount(Math.max(0, (this.discussion?.commentCount() ?? 0) - oldCount));
              window.addEventListener('focus', () => app.setTitleCount(0), {
                once: true
              });
            }
          });
        }
      } catch (e) {
        console.error('[Sonsuzus Pusher] DiscussionPage update hatası:', e);
      }
    };
    app.pusher.then(binding => {
      binding.pusher.bind('newPost', this.boundNewPostHandler);
    });
  });
  extend(DiscussionPage.prototype, 'onremove', function () {
    if (this.boundNewPostHandler) {
      app.pusher.then(binding => {
        binding.pusher.unbind('newPost', this.boundNewPostHandler);
      });
    }
  });
  extend(IndexPage.prototype, 'actionItems', items => {
    items.remove('refresh');
  });
  app.pusher.then(binding => {
    const channels = binding.channels;
    if (channels.user) {
      channels.user.bind('notification', () => {
        console.log('[Sonsuzus Pusher] Yeni bildirim (notification) algılandı.');
        if (app.session.user) {
          app.session.user.pushAttributes({
            unreadNotificationCount: (app.session.user.unreadNotificationCount() ?? 0) + 1,
            newNotificationCount: (app.session.user.newNotificationCount() ?? 0) + 1
          });
        }
        app.notifications.clear();
        m.redraw();
      });
    }
  });
});